int main(void) {
    int N;
    char s[200005];

    if (scanf("%d", &N) != 1) return 0;
    scanf("%s", s);

    // 0 = Sheep, 1 = Wolf
    // Try all possibilities for first two animals.
    for (int a0 = 0; a0 <= 1; a0++) {
        for (int a1 = 0; a1 <= 1; a1++) {
            int ans[200005];
            ans[0] = a0;
            ans[1] = a1;

            // Determine animals 2..N-1
            for (int i = 1; i <= N - 2; i++) {
                // If animal i is sheep:
                //   s[i]=='o' => ans[i-1] == ans[i+1]
                //   s[i]=='x' => ans[i-1] != ans[i+1]
                // If animal i is wolf, the statement is inverted.
                //
                // Unified rule:
                // ans[i+1] = ans[i-1] XOR (s[i]=='x') XOR ans[i]
                ans[i + 1] = ans[i - 1] ^ (s[i] == 'x') ^ ans[i];
            }

            // Check circular consistency for i=0 and i=N-1
            int ok = 1;

            // Check statement of animal 0
            {
                int same = (ans[N - 1] == ans[1]);
                int says_same = (s[0] == 'o');
                int truthful = (ans[0] == 0); // sheep truthful, wolf lying
                if (truthful) {
                    if (same != says_same) ok = 0;
                } else {
                    if (same == says_same) ok = 0;
                }
            }

            // Check statement of animal N-1
            {
                int same = (ans[N - 2] == ans[0]);
                int says_same = (s[N - 1] == 'o');
                int truthful = (ans[N - 1] == 0);
                if (truthful) {
                    if (same != says_same) ok = 0;
                } else {
                    if (same == says_same) ok = 0;
                }
            }

            if (ok) {
                for (int i = 0; i < N; i++) {
                    putchar(ans[i] == 0 ? 'S' : 'W');
                }
                putchar('\n');
                return 0;
            }
        }
    }

    printf("-1\n");
    return 0;
}

