            a[1] = second;

            for (int i = 1; i <= N - 2; i++) {
                int t = (s[i] == 'x') ? 1 : 0;
                a[i + 1] = a[i - 1] ^ a[i] ^ t;
            }

            bool ok = true;

            // Check i = 0
            {
                int t = (s[0] == 'x') ? 1 : 0;
                if ((a[N - 1] ^ a[1]) != (a[0] ^ t)) ok = false;
            }

            // Check i = N-1
            {
                int t = (s[N - 1] == 'x') ? 1 : 0;
