import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        String s = sc.next();
        sc.close();

        char[] species = new char[N];
        // Try all 4 possibilities for first two animals
        char[] possibleTypes = {'S', 'W'};
        for (char first : possibleTypes) {
            for (char second : possibleTypes) {
                species[0] = first;
                species[1] = second;
                if (check(N, s, species)) {
                    System.out.println(new String(species));
                    return;
                }
            }
        }
        System.out.println(-1);
    }

    static boolean check(int N, String answers, char[] species) {
        for (int i = 1; i < N; i++) {
            int prev = (i - 1 + N) % N;
            int next = (i + 1) % N;
            char answer = answers.charAt(i);
            if (species[i] == 'S') {
                // Honest: answer 'o' means same as neighbor, 'x' means different
                if (answer == 'o') {
                    species[next] = species[prev];
                } else { // 'x'
                    species[next] = (species[prev] == 'S') ? 'W' : 'S';
                }
            } else { // 'W' - liar
                if (answer == 'o') {
                    species[next] = (species[prev] == 'S') ? 'W' : 'S';
                } else { // 'x'
                    species[next] = species[prev];
                }
            }
        }
        // Check consistency for the last animal (index N-1) and first two
        // Last animal's answer should match its neighbors (species[N-2] and species[0])
        int last = N - 1;
        char ansLast = answers.charAt(last);
        char expectedNext = (species[last] == 'S') ?
            (ansLast == 'o' ? species[last-1] : (species[last-1] == 'S' ? 'W' : 'S')) :
            (ansLast == 'o' ? (species[last-1] == 'S' ? 'W' : 'S') : species[last-1]);
        if (expectedNext != species[0]) return false;

        // Also check the first animal's answer based on species[N-1] and species[1]
        char ansFirst = answers.charAt(0);
        char expectedFirstNext = (species[0] == 'S') ?
            (ansFirst == 'o' ? species[N-1] : (species[N-1] == 'S' ? 'W' : 'S')) :
            (ansFirst == 'o' ? (species[N-1] == 'S' ? 'W' : 'S') : species[N-1]);
        if (expectedFirstNext != species[1]) return false;

        return true;
    }
}

