import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();

        // 0 = Sheep (S), 1 = Wolf (W)
        for (int first = 0; first <= 1; first++) {
            for (int second = 0; second <= 1; second++) {
                int[] a = new int[N];
                a[0] = first;
                a[1] = second;

                for (int i = 1; i <= N - 2; i++) {
                    // Determine a[i+1] from a[i-1], a[i], and s[i]
                    // If animal i is Sheep:
                    //   'o' => neighbors same
                    //   'x' => neighbors different
                    // If animal i is Wolf: opposite
                    if (s.charAt(i) == 'o') {
                        a[i + 1] = (a[i] == 0) ? a[i - 1] : 1 - a[i - 1];
                    } else {
                        a[i + 1] = (a[i] == 0) ? 1 - a[i - 1] : a[i - 1];
                    }
                }

                if (isValid(a, s)) {
                    StringBuilder ans = new StringBuilder();
                    for (int x : a) ans.append(x == 0 ? 'S' : 'W');
                    System.out.println(ans);
                    return;
                }
            }
        }

        System.out.println(-1);
    }

    static boolean isValid(int[] a, String s) {
        int N = a.length;
        for (int i = 0; i < N; i++) {
            int left = a[(i - 1 + N) % N];
            int right = a[(i + 1) % N];
            boolean same = (left == right);
            char c = s.charAt(i);

            boolean statementTrue = (c == 'o') ? same : !same;

            if (a[i] == 0) { // Sheep tells truth
                if (!statementTrue) return false;
            } else { // Wolf lies
                if (statementTrue) return false;
            }
        }
        return true;
    }
}
